#include <iostream>
#include <fstream>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("punkty.txt");
    int n;
    plik >> n;
    int x[100], y[100];
    for (int i = 0; i < n; i++)
        plik >> x[i] >> y[i];
    int maxI = 0, maxJ = 1, minI = 0, minJ = 1;
    int maxD2 = 0;
    int minD2 = (x[0] - x[1]) * (x[0] - x[1]) + (y[0] - y[1]) * (y[0] - y[1]);
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int d2 = (x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j]);
            if (d2 > maxD2) { maxD2 = d2; maxI = i; maxJ = j; }
            if (d2 < minD2) { minD2 = d2; minI = i; minJ = j; }
        }
    }
    cout << fixed << setprecision(2);
    cout << "Najdalsza para: (" << x[maxI] << "," << y[maxI] << ") i (" << x[maxJ] << "," << y[maxJ] << "), odleglosc: " << sqrt((double)maxD2) << endl;
    cout << "Najblizsza para: (" << x[minI] << "," << y[minI] << ") i (" << x[minJ] << "," << y[minJ] << "), odleglosc: " << sqrt((double)minD2) << endl;
    return 0;
}
```

